export const HS_BY_CODE = new Map(HS_CODES.map((c) => [c.code, c]));

export function normalizeToken(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

export function fuzzyMatchHsCode(query: string, limit = 5): HsCode[] {
  const q = normalizeToken(query);
  if (!q) return [];
  const qTokens = q.split(" ").filter(Boolean);
  const scored = HS_CODES.map((c) => {
    const dTokens = normalizeToken(c.description).split(" ").filter(Boolean);
    if (!dTokens.length) return { code: c, score: 0 };
    let hits = 0;
    for (const t of qTokens) {
      if (dTokens.includes(t)) hits += 1;
      else if (dTokens.some((dt) => dt.startsWith(t) || t.startsWith(dt))) hits += 0.5;
    }
    return { code: c, score: hits / Math.max(qTokens.length, 1) };
  });
  return scored
    .filter((s) => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((s) => s.code);
}
